import functools

def _parse(v):
    # split build metadata
    main_part = v
    if '+' in main_part:
        main_part = main_part.split('+', 1)[0]
    if '-' in main_part:
        core, prerelease = main_part.split('-', 1)
    else:
        core, prerelease = main_part, None
    major, minor, patch = (int(x) for x in core.split('.'))
    return (major, minor, patch), prerelease

def _cmp_ident(a, b):
    a_num = a.isdigit()
    b_num = b.isdigit()
    if a_num and b_num:
        ai, bi = int(a), int(b)
        if ai < bi:
            return -1
        if ai > bi:
            return 1
        return 0
    if a_num and not b_num:
        return -1
    if not a_num and b_num:
        return 1
    if a < b:
        return -1
    if a > b:
        return 1
    return 0

def _cmp_prerelease(p1, p2):
    if p1 is None and p2 is None:
        return 0
    if p1 is None:
        return 1
    if p2 is None:
        return -1
    ids1 = p1.split('.')
    ids2 = p2.split('.')
    for a, b in zip(ids1, ids2):
        c = _cmp_ident(a, b)
        if c != 0:
            return c
    if len(ids1) < len(ids2):
        return -1
    if len(ids1) > len(ids2):
        return 1
    return 0

def _compare(v1, v2):
    core1, pre1 = _parse(v1)
    core2, pre2 = _parse(v2)
    if core1 < core2:
        return -1
    if core1 > core2:
        return 1
    return _cmp_prerelease(pre1, pre2)

def semver_sort(versions):
    indexed = list(enumerate(versions))
    def cmp(a, b):
        c = _compare(a[1], b[1])
        if c != 0:
            return c
        return a[0] - b[0]
    indexed.sort(key=functools.cmp_to_key(cmp))
    return [v for _, v in indexed]

